stock_uom = frappe.db.get_value('Item', doc.item_code, 'stock_uom')
if doc.uom != stock_uom:
    frappe.throw(f'Không được tạo/sửa Item Price với UOM {doc.uom}. Chỉ cho phép UOM gốc {stock_uom} của item {doc.item_code}.')

for item in doc.items:
    if item.posa_offer_applied == 0 and item.rate != item.price_list_rate:
        frappe.throw('Khong duoc sua rate tay cho item ' + item.item_code + '. Rate phai bang price_list_rate truoc khi ap Offer.')
    elif item.posa_offer_applied == 1 and item.rate > item.price_list_rate:
        frappe.throw('Khong duoc tang rate sau khi ap Offer cho item ' + item.item_code + '.')
